-- 416: Original BrillaPrep WASSCE Integrated Science beta questions, part 4 of 8 (sprint 1 batch 001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_416_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_416_guard;
INSERT INTO _migration_416_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_enr_b001_003' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_enr' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'When a dry cell powers a torch, the energy transformation that takes place is:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Electrical energy to chemical energy","B. Chemical energy to electrical energy","C. Heat energy to electrical energy","D. Mechanical energy to electrical energy"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A dry cell stores chemical energy and releases it as electrical energy in the circuit. The reverse change (electrical to chemical) occurs while charging a rechargeable cell.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_enr_b001_003' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_416_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_enr_b001_004' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_enr' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In a series circuit containing a battery and two lamps, the electric current is:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The same at every point in the circuit","B. Greater near the positive terminal of the battery","C. Permanently stored inside each lamp","D. Zero when the two lamps are identical"]' AND q.correct_answer IS 'A' AND q.explanation IS 'In a series circuit there is only one path, so the same charge passes every point each second; current is the same everywhere and is not used up by the lamps.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_enr_b001_004' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_416_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_enr_b001_005' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_enr' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A 12 V battery is connected across a 4 Ω resistor. The current flowing through the resistor is:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 48 A","B. 0.33 A","C. 3 A","D. 8 A"]' AND q.correct_answer IS 'C' AND q.explanation IS 'By Ohm’s law, I = V ÷ R = 12 V ÷ 4 Ω = 3 A. Multiplying the values (48 A) or inverting the division (0.33 A) misapplies the formula.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_enr_b001_005' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_416_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_enr_b001_006' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_enr' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A third identical lamp is added in series to a circuit containing a battery and two lamps. All the lamps become dimmer because:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The battery produces a lower voltage for series lamps","B. The total resistance increases, so the current decreases","C. The current is permanently used up by the lamps","D. The connecting wires stop the current"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Series resistances add, so the third lamp raises the total resistance; by I = V ÷ R the current falls and each lamp converts less power to light.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_enr_b001_006' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_416_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_enr_b001_007' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_enr' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is an advantage of connecting household lamps in parallel rather than in series?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Parallel lamps always use less wire than series lamps","B. The total resistance of the circuit becomes very large","C. The current is the same through every lamp","D. Each lamp receives the full supply voltage and can be switched independently"]' AND q.correct_answer IS 'D' AND q.explanation IS 'In parallel, each branch connects across the supply, so every lamp gets the full mains voltage and a switch or fault in one branch does not affect the others.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_enr_b001_007' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_416_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_enr_b001_008' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_enr' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Metals such as copper are good conductors of electricity mainly because:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. They contain free electrons that can drift through the metal","B. Their atoms are packed loosely with large spaces","C. Their protons are free to move through the lattice","D. Their nuclei vibrate when a battery is connected"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Free (delocalised) electrons drift through the metal lattice when a voltage is applied; this flow of charge is the current. Protons and nuclei stay fixed in the lattice.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_enr_b001_008' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
